const STATIC_TABS_BEFORE = [{ id: "home", label: "Strona główna" }, { id: "about", label: "O mnie" }];
const STATIC_TABS_AFTER = [{ id: "contact", label: "Kontakt" }];

const ALL_TABS = [
  ...STATIC_TABS_BEFORE,
  ...SUBJECTS.map((s) => ({ id: s.id, label: s.tabLabel || s.title })),
  ...STATIC_TABS_AFTER
];

const STORAGE_PREFIX = "unlocked:";

/* ---------------- Odblokowanie przedmiotów ---------------- */

function isUnlocked(subjectId) {
  return sessionStorage.getItem(STORAGE_PREFIX + subjectId) === "true";
}

function setUnlocked(subjectId) {
  sessionStorage.setItem(STORAGE_PREFIX + subjectId, "true");
}

function renderMaterialsList(materials) {
  if (!materials.length) return "<p>Materiały pojawią się tutaj wkrótce.</p>";
  const items = materials
    .map(
      (m) => `
      <li>
        <span class="material-name">${m.title}</span>
        <a class="material-download" href="${m.url}" download>Pobierz PDF</a>
      </li>`
    )
    .join("");
  return `<ul>${items}</ul>`;
}

function buildSubjectPanel(subject) {
  const section = document.createElement("section");
  section.className = "panel";
  section.id = `panel-${subject.id}`;

  const unlocked = isUnlocked(subject.id);
  const codeBadge = subject.code ? `<span class="subject-code">${subject.code}</span>` : "";

  section.innerHTML = `
    <div class="wrap subject-panel">
      <div class="subject-head">
        <h2>${subject.title}</h2>
        ${codeBadge}
      </div>

      <div class="subject-lock" ${unlocked ? "hidden" : ""}>
        <form>
          <input type="password" placeholder="Hasło do przedmiotu" autocomplete="off" />
          <button type="submit">Wejdź</button>
        </form>
        <p class="subject-error"></p>
      </div>

      <div class="subject-materials" ${unlocked ? "" : "hidden"}>
        <p class="subject-unlocked-note">Odblokowano — materiały poniżej.</p>
        ${renderMaterialsList(subject.materials)}
      </div>
    </div>
  `;

  const form = section.querySelector("form");
  const errorEl = section.querySelector(".subject-error");
  const lockEl = section.querySelector(".subject-lock");
  const materialsEl = section.querySelector(".subject-materials");

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const input = form.querySelector("input[type=password]");
    if (input.value === subject.password) {
      setUnlocked(subject.id);
      lockEl.hidden = true;
      materialsEl.hidden = false;
      errorEl.textContent = "";
    } else {
      errorEl.textContent = "Nieprawidłowe hasło. Spróbuj ponownie.";
      input.value = "";
      input.focus();
    }
  });

  return section;
}

function renderSubjectPanels() {
  const container = document.getElementById("subject-panels");
  SUBJECTS.forEach((subject) => container.appendChild(buildSubjectPanel(subject)));
}

/* ---------------- Zakładki / przełączanie paneli ---------------- */

function activateTab(tabId) {
  const validId = ALL_TABS.some((t) => t.id === tabId) ? tabId : "home";

  document.querySelectorAll(".panel").forEach((el) => {
    el.classList.toggle("is-active", el.id === `panel-${validId}`);
  });

  document.querySelectorAll(".tab").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.tabId === validId);
  });

  moveIndicator(validId);

  if (history.replaceState) {
    history.replaceState(null, "", `#${validId}`);
  }
}

function moveIndicator(activeId) {
  const activeBtn = document.querySelector(`.tab[data-tab-id="${activeId}"]`);
  const indicator = document.querySelector(".tab-indicator");
  if (!activeBtn || !indicator) return;
  indicator.style.left = `${activeBtn.offsetLeft}px`;
  indicator.style.width = `${activeBtn.offsetWidth}px`;
}

function renderTabs() {
  const nav = document.getElementById("tabs");
  nav.innerHTML = "";
  ALL_TABS.forEach((tab) => {
    const btn = document.createElement("button");
    btn.className = "tab";
    btn.type = "button";
    btn.dataset.tabId = tab.id;
    btn.textContent = tab.label;
    btn.addEventListener("click", () => activateTab(tab.id));
    nav.appendChild(btn);
  });
  const indicator = document.createElement("span");
  indicator.className = "tab-indicator";
  nav.appendChild(indicator);
}

